_NS = uuid.NAMESPACE_DNS
_MSK = ZoneInfo("Europe/Moscow")
_REFUND_KOPECKS = 500_000  # 5 000 RUB -- negative/refund boundary
_LARGE_KOPECKS = 999_999_999_00  # ~9 999 999.99 RUB -- BigInteger boundary
_PAGINATION_COUNT = 30  # forces /clients page 2+ regardless of demo volume


def _uid(key: str) -> uuid.UUID:
    return uuid.uuid5(_NS, key)


async def _upsert(session: AsyncSession, model: type, **values: object) -> None:
    """ON CONFLICT (id) DO NOTHING -- deterministic-id idempotency (D-122-11)."""
    stmt = pg_insert(model).values(**values).on_conflict_do_nothing(index_elements=["id"])
    await session.execute(stmt)


async def _get_owner(session: AsyncSession) -> User:
    owner = await session.scalar(
        select(User).where(User.role == Role.OWNER).order_by(User.created_at)
    )
    if owner is None:
        print("ERROR: run `uv run python -m scripts.seed_demo_data` first.", file=sys.stderr)
        raise SystemExit(1)
    return owner


async def _get_base_plan(session: AsyncSession) -> MembershipPlan:
    plan = await session.scalar(
        select(MembershipPlan)
        .where(MembershipPlan.active.is_(True))
        .where(MembershipPlan.deleted_at.is_(None))
        .order_by(MembershipPlan.created_at)
    )
    if plan is None:
        print("ERROR: no active MembershipPlan. Run seed_demo_data first.", file=sys.stderr)
        raise SystemExit(1)
    return plan


