async def _seed_pagination_clients(session: AsyncSession, owner: User) -> None:
    """Axis 3 -- enough rows to force /clients pagination past page 1."""
    for n in range(1, _PAGINATION_COUNT + 1):
        await _upsert(
            session,
            Client,
            id=_uid(f"edge_pagination_client_{n:03d}@fixture.local"),
            last_name="EdgePagination",
            first_name=f"Client{n:03d}",
            phone=f"+7900200{n:04d}",
            created_by_user_id=owner.id,
        )
    print(f"Seeded {_PAGINATION_COUNT} pagination clients (idempotent).")


