async def _seed_dst_tz_boundary(session: AsyncSession, owner: User, plan: MembershipPlan) -> None:
    """Axis 6 -- Europe/Moscow UTC-vs-local day-rollover boundary.

    Russia abolished DST in 2011 (permanent MSK, UTC+3 -- no literal
    spring-forward/fall-back gap exists). The real TZ risk here is the
    UTC-vs-MSK calendar-day rollover: 00:30 MSK on 2026-01-01 is
    2025-12-31T21:30:00Z -- code deriving "today" via UTC instead of the
    Europe/Moscow local date would misfile this visit under the wrong day.
    """
    dst_client_id = _uid("edge_dst_client@fixture.local")
    await _upsert(
        session,
        Client,
        id=dst_client_id,
        last_name="EdgeDstTz",
        first_name="Client",
        phone="+79001009005",
        email="edge_dst_client@fixture.local",
        created_by_user_id=owner.id,
    )
    dst_membership_id = _uid("edge_dst_membership@fixture.local")
    checked_in_at = datetime(2026, 1, 1, 0, 30, tzinfo=_MSK)
    gym_date = checked_in_at.date()  # 2026-01-01 MSK; UTC instant is 2025-12-31T21:30:00Z
    await _upsert(
        session,
        Membership,
        id=dst_membership_id,
        client_id=dst_client_id,
        plan_id=plan.id,
        plan_name_snapshot=plan.name,
        duration_days_snapshot=plan.duration_days,
        price_kopecks_snapshot=plan.price_kopecks,
        freeze_days_limit_snapshot=plan.freeze_days_limit,
        start_date=datetime(2025, 12, 1, tzinfo=_MSK).date(),
        end_date=datetime(2026, 1, 31, tzinfo=_MSK).date(),
        status="active",
    )
    await _upsert(
        session,
        Visit,
        id=_uid("edge_dst_visit@fixture.local"),
        client_id=dst_client_id,
        membership_id=dst_membership_id,
        checked_in_at=checked_in_at,
        gym_date=gym_date,
        channel="reception",
        checked_in_by=owner.id,
    )
    print("Seeded Europe/Moscow UTC-vs-local day-rollover boundary visit.")


