async def _run() -> int:
    settings = get_settings()
    db_url = str(settings.database_url)
    if "localhost" not in db_url and "postgres:5432" not in db_url:
        # D-122-13 / T-122-05: docker-compose only, never k3d/staging/prod.
        print("ERROR: refuses to run against non-local DATABASE_URL (D-122-13).", file=sys.stderr)
        return 1

    engine = create_async_engine(db_url)
    sessionmaker = async_sessionmaker(engine, expire_on_commit=False)
    try:
        async with sessionmaker() as session:
            owner = await _get_owner(session)
            plan = await _get_base_plan(session)
            await _seed_null_and_empty_history(session, owner)
            await _seed_pagination_clients(session, owner)
            await _seed_money_boundaries(session, owner, plan)
            await _seed_dst_tz_boundary(session, owner, plan)
            await _seed_empty_chat_thread(session, owner)
            await session.commit()
            print("Edge-case seed complete (additive, idempotent). See v4.1-EDGE-SEED-MATRIX.md.")
    finally:
        await engine.dispose()
    return 0


def main() -> int:
    return asyncio.run(_run())


if __name__ == "__main__":
    raise SystemExit(main())
